/// <summary>
/// This class defines the data contract for the Inventory On-hand Report business event.
/// </summary>
[DataContract]
final class METInventOnhandStorageBusinessContract extends BusinessEventsContract
{
    public CreatedTransactionId inventoryOnhandReportId;
    public ExecutionNameInventOnhand inventoryOnhandReportName;
    public ExecutionTimeInventOnhand inventoryOnhandReportExecutionTime;

}

