[DataMember('InventoryOnhandReportId'), BusinessEventsDataMember("@SYS90979")]
public CreatedTransactionId parmInventoryOnhandReportId(CreatedTransactionId _inventoryOnhandReportId = inventoryOnhandReportId)
{
    inventoryOnhandReportId = _inventoryOnhandReportId;

    return inventoryOnhandReportId;
}

