/// <param name = "_inventoryOnhandReportName">ExecutionNameInventOnhand</param>
/// <param name = "_inventoryOnhandReportExecutionTime">ExecutionTimeInventOnhand</param>
/// <returns>METInventOnhandStorageBusinessContract</returns>
public static METInventOnhandStorageBusinessContract newFromParameters(CreatedTransactionId _inventoryOnhandReportId, ExecutionNameInventOnhand _inventoryOnhandReportName, ExecutionTimeInventOnhand _inventoryOnhandReportExecutionTime)
{
    METInventOnhandStorageBusinessContract contract = new METInventOnhandStorageBusinessContract();
    contract.inventoryOnhandReportId = _inventoryOnhandReportId;
    contract.inventoryOnhandReportName = _inventoryOnhandReportName;
